script:
# --- STEP 1: PARSING & INITIAL VALIDATION ---
try:
    data = frappe.form_dict
    frappe.log_error(
        message="Create Employee API execution initiated.\nPayload:\n" + repr(dict(frappe.form_dict)),
        title="Create Employee API - Step 1: Payload Received"
    )

    use_type = str(data.get("useTypeIDF", "")).strip()
    if use_type not in ["3", "4", "6"]:
        frappe.throw("Invalid useTypeIDF. Allowed values are 3 (Care Professional), 4 (Employee), 6 (Careprovider)")

    # --- Helpers ---
    def normalize(val):
        return (val or "").strip().lower()

    def generate_normalized_username(user_id_input):
        """Matches the custom_login pattern for username/email generation."""
        username = str(user_id_input or "").replace("@bmcinternal.com", "")
        if "@" in username:
            username = username + "bmcinternal.com"
        else:
            username = username + "@bmcinternal.com"
        return "-".join(username.split())

    def clean_val(val):
        """Converts null/nan/undefined strings into clean empty strings."""
        s = str(val or "").strip()
        if s.lower() in ["nan", "null", "none", "undefined"]:
            return ""
        return s

    # --- Default Company ---
    company_name = "Brihanmumbai Municipal Corporation"
    company_norm = normalize(company_name)

    # --- Branch Input (Accepts 'branch' OR 'company' from payload) ---
    branch_input = clean_val(data.get("branch") or data.get("company"))

    # --- Validate required fields ---
    required_fields = [
        "citizenidp", "first_name", "gender", "date_of_birth",
        "date_of_joining", "status", "ph_no", "user_id",
        "address"
    ]

    if use_type in ["3", "4"]:
        required_fields.extend(["department", "designation"])

    if use_type in ["4", "6"]:
        if not branch_input:
            frappe.throw("Missing required field: branch (or company in payload)")

    # --- Clean names and optional values ---
    first_name = clean_val(data.get("first_name"))
    last_name = clean_val(data.get("last_name"))
    middle_name = clean_val(data.get("middle_name"))
    salutation = clean_val(data.get("salutation"))
    gender = clean_val(data.get("gender"))
    status = clean_val(data.get("status"))

    # --- UPDATED ADDITION: Strict Mapping for Employment Type ---
    raw_emp_type = clean_val(data.get("employment_type")).lower()
    emp_type_map = {
        "permanent": "Full-time",
        "full-time": "Full-time",
        "fulltime": "Full-time",
        "contractual": "Contract",
        "contract": "Contract"
    }
    # If not found in the map, it becomes an empty string ("")
    employment_type_input = emp_type_map.get(raw_emp_type, "")

    # --- UPDATED ADDITION: Duplicate Mobile Number Check ---
    ph_no = clean_val(data.get("ph_no"))
    if ph_no:
        # Check if the number already exists in User or Employee masters
        user_dup = frappe.db.exists("User", {"mobile_no": ph_no})
        emp_dup = frappe.db.exists("Employee", {"cell_number": ph_no})

        if user_dup or emp_dup:
            ph_no = "" # Found a duplicate, null it out so it doesn't crash the database

except Exception as e:
    frappe.log_error(title="Create Employee API - Step 1 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 400, "status": "error", "error": f"Validation Stage Failed: {str(e)}"}
    raise  

# --- STEP 2: COMPANY & BRANCH RESOLUTION ---
try:
    # 1. Ensure Default Company exists in Master
    if not frappe.db.exists("Company", company_name):
        frappe.get_doc({
            "doctype": "Company",
            "company_name": company_name,
            "default_currency": "INR"
        }).insert(ignore_permissions=True)

    # 2. Resolve or Create Branch Master
    branch_name = None
    if branch_input:
        branch_norm = normalize(branch_input)
        for b in frappe.get_all("Branch", fields=["name"]):
            if normalize(b.name) == branch_norm:
                branch_name = b.name
                break
        if not branch_name:
            # Auto-create Branch master if missing
            branch_doc = frappe.get_doc({
                "doctype": "Branch",
                "branch": branch_input
            }).insert(ignore_permissions=True)
            branch_name = branch_doc.name

except Exception as e:
    frappe.log_error(title="Create Employee API - Step 2 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 404, "status": "error", "error": f"Company/Branch Resolution Failed: {str(e)}"}
    raise

# --- STEP 3: SALUTATION MASTER CHECK/CREATE ---
try:
    if salutation and not frappe.db.exists("Salutation", {"salutation": salutation}):
        frappe.get_doc({
            "doctype": "Salutation",
            "salutation": salutation
        }).insert(ignore_permissions=True)
except Exception as e:
    frappe.log_error(title="Create Employee API - Step 3 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Salutation Insertion Failed: {str(e)}"}
    raise

# --- STEP 4: DEPARTMENT RESOLUTION ---
try:
    department_name = None
    department_input = clean_val(data.get("department"))
    if department_input:
        dept_norm = normalize(department_input)
        for d in frappe.get_all("Department", fields=["name", "department_name", "company"]):
            if normalize(d.department_name) == dept_norm and normalize(d.company or "") == company_norm:
                department_name = d.name
                break
        if not department_name:
            department = frappe.get_doc({
                "doctype": "Department",
                "department_name": department_input,
                "company": company_name
            }).insert(ignore_permissions=True)
            department_name = department.name
except Exception as e:
    frappe.log_error(title="Create Employee API - Step 4 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Department Logic Failed: {str(e)}"}
    raise

# --- STEP 5: DESIGNATION RESOLUTION ---
try:
    designation_name = None
    designation_input = clean_val(data.get("designation"))
    if designation_input:
        desg_norm = normalize(designation_input)
        for d in frappe.get_all("Designation", fields=["name", "designation_name"]):
            if normalize(d.designation_name) == desg_norm:
                designation_name = d.name
                break
        if not designation_name:
            designation = frappe.get_doc({
                "doctype": "Designation",
                "designation_name": designation_input
            }).insert(ignore_permissions=True)
            designation_name = designation.name
except Exception as e:
    frappe.log_error(title="Create Employee API - Step 5 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Designation Logic Failed: {str(e)}"}
    raise

# --- STEP 5B: EMPLOYMENT TYPE RESOLUTION ---
try:
    # If blank, this safely skips. If valid, ensures it exists in the master list.
    if employment_type_input and not frappe.db.exists("Employment Type", employment_type_input):
        frappe.get_doc({
            "doctype": "Employment Type",
            "employee_type_name": employment_type_input
        }).insert(ignore_permissions=True)
except Exception as e:
    frappe.log_error(title="Create Employee API - Step 5B Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Employment Type Logic Failed: {str(e)}"}
    raise

# --- STEP 6: USER RECORD CREATION ---
try:
    # Generate User Name/Email matching custom_login format
    user_email = generate_normalized_username(data["user_id"])
    user_prefix = user_email.split("@")[0]

    user_payload = {
        "doctype": "User",
        "email": user_email,
        "first_name": first_name,
        "middle_name": middle_name,
        "last_name": last_name,
        "username": user_prefix,
        "send_welcome_email": 0,
        "company": company_name,
        "new_password": f"{user_prefix}@123",
        "gender": gender,
        "enabled": 1,
        "mobile_no": ph_no,  # <--- UPDATED: Uses our pre-checked safe variable
        "default_workspace": "Employee Dashboard",
        "birth_date": data["date_of_birth"],
        "default_app": "hrms",
        "user_type": "System User",
    }

    if use_type == "6": 
        user_payload.update({"module_profile": "HR", "role_profile_name": "hr_admin"})
    else:
        user_payload.update({"module_profile": "Employee", "role_profile_name": "User_Custom"})

    user = frappe.get_doc(user_payload)
    user.insert(ignore_permissions=True)

except Exception as e:
    frappe.db.rollback()
    frappe.log_error(title="Create Employee API - Step 6 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"System User generation failed: {str(e)}"}
    raise

# --- STEP 7: EMPLOYEE DOCUMENT CREATION ---
try:
    employee_data = {
        "doctype": "Employee",
        "first_name": first_name,
        "middle_name": middle_name,
        "last_name": last_name,
        "gender": gender,
        "salutation": salutation,
        "date_of_birth": data["date_of_birth"],
        "date_of_joining": data["date_of_joining"],
        "status": status,
        "company": company_name,
        "branch": branch_name,
        "cell_number": ph_no,  # <--- UPDATED: Uses our pre-checked safe variable
        "current_address": clean_val(data.get("address")),
        "user_id": user.name,
        "create_user_permission": 0 if use_type == "6" else 1
    }

    if department_name:
        employee_data["department"] = department_name
    if designation_name:
        employee_data["designation"] = designation_name

    if employment_type_input:
        employee_data["employment_type"] = employment_type_input

    employee = frappe.get_doc(employee_data)
    employee.insert(ignore_permissions=True)

except Exception as e:
    frappe.db.rollback()
    frappe.log_error(title="Create Employee API - Step 7 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Employee Profile insertion failed: {str(e)}"}
    raise

# --- STEP 8: PERMISSIONS MAPPING & DB COMMIT ---
try:
    if use_type == "6" and branch_name:
        if not frappe.db.exists("User Permission", {"user": user.name, "allow": "Branch", "for_value": branch_name}):
            user_permission = frappe.get_doc({
                "doctype": "User Permission",
                "user": user.name,
                "allow": "Branch",
                "for_value": branch_name,
                "apply_to_all_doctypes": 1
            })
            user_permission.insert(ignore_permissions=True)

    frappe.db.commit()

    frappe.response["message"] = {
        "http_status_code": 200,
        "status": "success",
        "employee_id": employee.name,
        "user_id": user.name,
        "citizenidp": data["citizenidp"]
    }

except Exception as e:
    frappe.db.rollback()
    frappe.log_error(title="Create Employee API - Step 8 Fail", message=f"ERROR: {str(e)}")
    frappe.response["message"] = {"http_status_code": 500, "status": "error", "error": f"Database finalization crashed: {str(e)}"}
